import {describe, it, expect} from 'vitest';
import type {IncomingMessage, OutgoingMessage, ListSessionsMessage, SessionListMessage} from './messages.js';

describe('Message types', () => {
  it('should allow ListSessionsMessage in IncomingMessage', () => {
    // This is a type-level test, we use a value to verify it at runtime/compile-time
    const msg: IncomingMessage = {
      type: 'list_sessions',
      limit: 10,
      before: {
        sessionId: 'abc',
        updatedAt: '2023-01-01T00:00:00Z'
      }
    } as ListSessionsMessage;
    expect(msg.type).toBe('list_sessions');
  });

  it('should allow SessionListMessage in OutgoingMessage', () => {
    const msg: OutgoingMessage = {
      type: 'session_list',
      sessions: [
        {
          sessionId: 'abc',
          createdAt: '2023-01-01T00:00:00Z',
          updatedAt: '2023-01-01T00:00:00Z'
        }
      ]
    } as SessionListMessage;
    expect(msg.type).toBe('session_list');
  });
});

