import {describe, it, expect} from 'vitest';
import type {IncomingMessage, OutgoingMessage, ListSessionsMessage, SessionListMessage} from './messages.js';

describe('Message types', () => {
  it('ListSessionsMessage has correct type discriminator', () => {
    const msg: ListSessionsMessage = {
      type: 'list_sessions',
      limit: 10,
      before: {
        sessionId: 'abc',
        updatedAt: '2023-01-01T00:00:00Z'
      }
    };
    expect(msg.type).toBe('list_sessions');
    expect(msg.limit).toBe(10);
    expect(msg.before?.sessionId).toBe('abc');
  });

  it('SessionListMessage has correct type discriminator', () => {
    const msg: SessionListMessage = {
      type: 'session_list',
      sessions: [
        {
          sessionId: 'abc',
          createdAt: '2023-01-01T00:00:00Z',
          updatedAt: '2023-01-01T00:00:00Z'
        }
      ]
    };
    expect(msg.type).toBe('session_list');
    expect(msg.sessions).toHaveLength(1);
    expect(msg.sessions[0].sessionId).toBe('abc');
  });
});
